 Object* nearest(){Object* best=nullptr;float d=36;for(auto& o:map.objects){if((o.type=="antidote"&&antidoteParts[o.props.value("component",0)])||(o.type=="cache"&&supplyUsed[o.props.value("index",0)]))continue;if(o.type=="spawn"||o.type=="debris"||o.type=="hazard"||(o.type=="mopweapon"&&hasMop))continue;if(o.type!="door"&&o.type!="gate"&&!map.ray(player,o.pos()))continue;if((o.type=="keycard"&&keycard)||(o.type=="serum"&&serum))continue;float dd=dist(player,o.pos());if(o.type=="door"||o.type=="gate"){dd=dist(player,V(std::clamp(player.x,o.b.x,o.b.x+o.b.w),std::clamp(player.y,o.b.y,o.b.y+o.b.h)));}if(dd<d){d=dd;best=&o;}}return best;}
 std::string label(const Object& o){auto t=o.type;if(t=="antidote")return o.props.value("label",std::string("Recover ingredient"));if(t=="labnote")return "Read recovery protocol";if(t=="cache")return "Search emergency supply locker";if(t=="mentor")return "Talk to Kamila Batkuldinova";if(t=="officeprop"){auto k=o.props.value("kind",std::string("AITU"));return "Inspect: "+std::string(k=="printer"?"printer":k=="cooler"?"water cooler":k=="files"?"files":k=="desk"?"sysadmin desk":k=="server"?"server":"note");}if(t=="mopweapon")return "Take the mop";if(t=="keyrack")return lectureKey?"Key rack: key 18 already collected":"Examine the keys and caretaker's note";if(t=="cardreader")return "Swipe card: passage to block 2";if(t=="locker")return hasPhone?"My locker: gear collected":"My locker: enter PIN";if(t=="projector")return projectorExamined?"Press PLAY":"Examine the PLAY button";if(t=="serum")return "Assemble the antidote";if(t=="powerpanel")return powerRestored?"Backup power is online.":"Repair backup power circuits";if(t=="vent")return ventStage==0?"Connect the antidote cartridge":ventStage==1?"Select channel: ALL BLOCKS":"Start central air conditioning";if(t=="bottles")return "Take bottles (up to 5)";if(t=="teacher")return "Talk to Duman Adilet";if(t=="laptop")return laptopUnlocked?"Read the first objective":"Unlock computer";if(t=="keycard")return "Pick up access card";if(t=="exit")return "Emergency exit";if(t=="gate")return o.open?"Passage open":o.b.x>100*T?"Use the card at the corridor reader.":"Restore backup power in block 2.";if(t=="door")return o.open?"Close door":"Open door";if(t=="lightpanel")return "Check emergency lighting";if(t=="bell")return "Ring the bell";if(t=="vending")return "Start vending machine";if(t=="schedule")return "Read timetable";if(t=="notice")return "Evacuation plan";if(t=="directory")return "Room directory";if(t=="camera")return "Surveillance camera";if(t=="secret")return "Search the hidden cabinet";return "Read note";}
#include "AntidoteQuest.inl"
 void interact(Object& o){auto t=o.type;if(t=="note"||t=="notice"||t=="directory")audio.play("paper.wav");
  if(t=="labnote"){int i=o.props.value("component",0);protocolSeen[i]=true;savePoint();audio.play("paper.wav");say("RECOVERY PROTOCOL / BLOCK "+std::to_string(3-i),o.props.value("text",std::string("Check the nearby station.")));return;}
  if(t=="antidote"){int i=o.props.value("component",0);if(antidoteParts[i])return;if(!notesRecorded){notify("Watch the biologist's recording before handling the recovery equipment.");return;}if(i==1&&!powerRestored){notify("Restore block-2 backup power before starting the filter.");return;}if(i==2&&!antidoteParts[1]){notify("Recover the stabilizer in block 2 first.");return;}if(!protocolSeen[i]){notify("Read the protocol card beside this recovery station first.");return;}beginRemedy(i);return;}
  if(t=="cache"){int i=o.props.value("index",0);if(!hasPhone){notify("Collect your bag first.");return;}if(supplyUsed[i])return;supplyUsed[i]=true;bottles=std::min(5,bottles+2);audio.play("locker-open.wav");savePoint();say("STUDENT","Emergency supplies: two sealed bottles and a campus note.\n"+o.props.value("text",std::string("Someone left these for the next survivor.")));return;}
  if(t=="mentor"){say("Kamila Batkuldinova",serum?"The cartridge is ready. Insert it in the ventilation console, choose ALL BLOCKS and start the air conditioning.":ingredientCount()==3?"You made it! Put the stabilizer in first, then the culture base and the catalyst. The blending desk is beside the wall. I will stay here while you prepare the antidote.":"I am Kamila Batkuldinova. This room is secure, but we cannot leave everyone behind. We need all three ingredients. Your phone has the next recovery location.");return;}
  if(t=="officeprop"){audio.play(o.props.value("sound",std::string("paper.wav")));say(o.props.value("kind",std::string("AITU")),o.props.value("text",std::string("Someone was working here before the alarm.")));return;}
  if(t=="mopweapon"){if(hasMop)return;hasMop=true;audio.play("mop-pickup.wav");savePoint();say("STUDENT","A mop! At least I can defend myself.\nG or SPACE stuns the closest infected person.\nMove close enough to see the G prompt.\nThe swing aims automatically, then briefly cools down.");return;}
  if(t=="door"){if(o.name=="LECTURE DOOR"&&!lectureKey){notify("The lecture hall is locked. Look in the service room at the far right.");return;}if(o.name=="361 DOOR"&&!laptopUnlocked){notify("Unlock the lectern computer first.");return;}if(o.open){bool occupied=o.b.contains(player,7);for(auto& z:map.zombies)occupied|=o.b.contains(z.pos,7);if(occupied){notify("Step away from the doorway.");return;}}o.open=!o.open;audio.play(o.open?"door-open.wav":"door-close.wav");return;}
  if(t=="keyrack"){if(!hasPhone){notify("Collect your locker gear first.");return;}if(lectureKey){notify("Key 18 is yours. The lecture hall is unlocked.");return;}keyRevealed=true;keyChoice=0;keyFeedback.clear();audio.play("keys.wav");screen=Screen::Keys;return;}
  if(t=="cardreader"){if(cardSwiped){notify("The card has already been accepted.");return;}if(!keycard){notify("You need the card from the lecture lectern.");return;}if(!notesRecorded){notify("Watch the lecture recording first.");return;}swipeX=144;swipeAge=0;swipeDragging=false;swipeStatus="SWIPE THE CARD FROM LEFT TO RIGHT";screen=Screen::Swipe;return;}
  if(t=="gate"){if(!o.open&&o.b.x>100*T){interact(*map.type("cardreader"));return;}if(!o.open)notify(label(o));return;}
  if(t=="laptop"){audio.play("keyboard.wav");if(laptopUnlocked){say(story["quest"]["speaker"],story["quest"]["text"]);messagePortrait=1;}else{typed.clear();screen=Screen::Laptop;}return;}
  if(t=="teacher"){guarding=true;say("Duman Adilet","I will guard this door so the infected cannot get in.\nCheck the computer; it has our first clue.\nThe password is decimal 10 converted to binary.");return;}
  if(t=="locker"){audio.play("locker-open.wav");if(!laptopUnlocked){notify("Check the computer in 361 first.");return;}if(hasPhone){say("STUDENT","My phone, bag and personal belongings are with me.");return;}if(!lockerExamined){lockerExamined=true;say("STUDENT","My locker. What did I choose as the PIN?\nMy birth year. Of course: 2008!");afterMessage="locker";}else{typed.clear();screen=Screen::Locker;}return;}
  if(t=="keycard"){if(!hasPhone){notify("Collect your phone and bag first.");return;}keycard=true;audio.play("card-pickup.wav");savePoint();notify("Block-3 card found. Use the corridor reader after collecting the base.");return;}
  if(t=="projector"){if(!hasPhone){notify("Collect the phone first so you can save the clues.");return;}if(!projectorExamined){projectorExamined=true;say("STUDENT","Why is there a PLAY button on the projector?\nSomeone left a recording. I should watch it and save the plan.");return;}screen=Screen::Video;videoIndex=0;videoClock=messageAge=0;audio.play("projector.wav");return;}
  if(t=="serum"){if(ingredientCount()!=3){notify("The antidote needs three ingredients, one from each block. Check your phone.");return;}if(!powerRestored){notify("Restore the backup supply before using the blending desk.");return;}if(serum){notify("The antidote cartridge is ready.");return;}beginRemedy(3);return;}
  if(t=="powerpanel"){if(!notesRecorded){notify("Watch the block-3 lecture recording first.");return;}if(powerRestored){notify("Backup power is already online. HVAC is ready.");return;}wireSelected=-1;wireStatus="Match the colors and numbers.";screen=Screen::Wiring;return;}
  if(t=="vent"){if(!notesRecorded||!serum||!powerRestored){notify("You need the rescue plan, backup power and the complete antidote.");return;}if(ventStage<2){audio.play(ventStage==0?"cartridge.wav":"channel.wav");ventStage++;notify(ventStage==1?"Cartridge connected. Select ALL BLOCKS [E]":"Campus channel selected. Start air conditioning [E]");savePoint();}else{screen=Screen::Ending;ending=0;escaped=true;finalTeacherPlaced=finalTeacherReady=false;audio.play("vent.wav");toastTime=0;}return;}
  if(t=="exit"){say("STUDENT","I cannot leave everyone behind.\nI must reach 354 and distribute the antidote.");return;}
  if(t=="bottles"){if(noiseCooldown>0)notify("Supplies are restocking. Wait a moment.");else{bottles=5;noiseCooldown=8;notify("Bottles: 5 / Q or RMB - throw toward cursor");}return;}
  if(t=="lightpanel"){audio.play("switch.wav");flicker=!flicker;notify(flicker?"The power is unstable.":"Emergency lighting has stabilized.");}
  else if(t=="bell"||t=="vending"){if(noiseCooldown>0)notify("The device is cooling down. Try again shortly.");else{noise(o.pos(),t=="bell"?450.f:235.f,t=="bell"?5.f:9.f);noiseCooldown=t=="bell"?10.f:12.f;audio.play(t=="bell"?"notification.wav":"vending.wav");notify(t=="bell"?"The bell distracted nearby infected.":"The machine is humming. Is the route clear?");}}
  else if(t=="schedule"){audio.play("paper.wav");say("TIMETABLE / AITU","08:30 - Discrete Mathematics, 361.\n10:00 - Independent study.\nFor once, I arrived before everyone else.");}
  else if(t=="notice")say("AITU WAYFINDING","Personal locker 08 is at the corridor's right end.\nThe main lecture hall is opposite the passage.");
  else if(t=="directory")say("AITU ROOM DIRECTORY","361 - Discrete Mathematics, block 3.\n354 - safe classroom, block 1.\nBackup power - lower-left room in block 2.");
  else if(t=="camera"){audio.play("camera.wav");screen=Screen::Camera;notify("Live feed / ESC to leave");}
  else if(t=="note")say("DESK NOTE",o.props.value("text",std::string("Never leave your assignments until the last minute.\nEven during an outbreak.\nBinary place values from the right: 1, 2, 4, 8.")));
  else if(t=="secret"){secret=true;say("HIDDEN CABINET","You found FINAL_final_v7_REAL.cpp!\nThe note reads: Backups are a student's best friend.");}
 }

 void throwBottle(){if(!hasPhone){notify("The bottles are in my bag, inside my locker.");return;}if(bottles<=0){notify("No bottles left. Move quietly.");return;}V target=mouse+cam;V delta=target-player;float distance=std::clamp(glm::length(delta),32.f,220.f);V direction=unit(delta);if(glm::length(direction)<.1f)direction=V(1,0);Projectile p;p.start=p.pos=player+direction*9.f;p.duration=distance/265.f;p.velocity=direction*265.f;projectiles.push_back(p);bottles--;throws++;audio.play("bottle-throw.wav");}
 void impact(V p){noise(p,280,7);audio.play("impact.wav");for(auto& z:map.zombies)if(dist(z.pos,p)<19){z.stun=2;z.state=1;z.goal=p;z.memory=7;} }
